using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle;

internal sealed class OddHalfParentExchangeDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "An actual odd-half negative parent gives a strict physical exchange, either by four fresh LARGE insertions or by reusing its old prefix occurrence.",
        H("Odd-half negative-parent exchanges"),
        Blocks(
            Paragraph(Text("Let k>=3, t be natural, rho=finRotate k, N=2^k-1=4Q-1 and C=2Q-1. The centered dyadic source f(i)=s(k,t,i) is on physical labels Fin k and its complete physical source has sum zero. Legal means physical Nodup and every natural take-prefix mass from ORIGINAL zero in [0,C], including zero and overlength takes. LARGE means abs(f)>=Q and SMALL means abs(f)<Q. G counts unused LARGE, H sums 3^abs(f) over used LARGE, U counts unused physical labels, and J=(G,H,U) is ordered lexicographically. Equal source values at different labels remain different resources.")),
            Paragraph(Text("Write W=A,[x],T0,[y],T1,[zpen],T2,[z],E, S=T0,T1,T2,E, F=A,[x],T0,[y] and Rsmall=T1,T2,E. The native data are n=rho(p), x=rho(n), f(p)=P>0, f(n)=-D with D>=Q, N<3P, and the actual beta=rho^(-1)(y), gamma=rho^(-1)(beta), a=rho^(-1)(gamma). W is Legal, p,n,beta are absent from ALL W, every S occurrence is SMALL, Q<=-f(z)<=D, and Q<=-f(zpen)<=L=f(beta). Put Y=-f(y)>P, assume Y odd and L mod 4=2, and retain the actual placement gamma in A. With d=P-D, B=C-P, delta=Y-P, a0=mass(A), h=mass(W) and v=mass(F), the residual is B<h<D, (Y+1)/2-d<=v<d, D<=3d-4, 3delta<=d-2 and D>2d+2delta+7. The zpen bound is the surviving odd-first-negative placement bound, not an assertion that an arbitrary first-negative word satisfies it.")),
            Paragraph(Text("Native expanding geometry gives N=2P+D, r=f(x)=2P-D and Q<=D<P<r<=C. Actual inverse-source parity gives 2L=N-Y, 2q=L for q=f(gamma), q odd, and f(a)=-M with 2M=N-q. Thus a is the actual negative LARGE parent, with no positive quarter-parent. Define e=M-P, theta=M-D=d+e, tau=P-L and kappa=e-tau. The source equations and residual imply D<L<P<Y<M<r, 0<theta<Q, 0<e<d, e>B-d, v>e, v>tau and delta+kappa<B-d. Old legality at x also gives 0<=a0<=B-d. These implications supply the new gates; they are not hypotheses requiring a favorable arrival or endpoint.")),
            Describe.Lean(DescribeId.Create("actual-unused-odd-half-parent-exchange"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/OddHalfParentExchange.actualSource_unused_oddHalf_parent_exchange_full"),
                H("A fresh actual negative parent improves G by two"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Assume actual a is absent from ALL W. Keep F literally and set I0=[p,a,beta,n], V0=F,I0 and Ret0=T1,[zpen],T2,[z],E. The four appended heights are v+P, v-e, v-e+L and v-e+L-D. They are in [0,C]: v<d<B controls the first upper gate, v>e controls the negative-parent step, L<P controls the next upper gate and L>D controls the final lower gate. Keeping the original F and appending these gates proves every natural zero-start prefix legal. Distinct values of the four inserted labels prove their mutual physical distinctness; absence is nevertheless required for the actual labels, not for their values.")),
                    Paragraph(Text("The whole physical identity is V0,Ret0 permutes W,I0. Ordinary Inventory supplies physical Nodup, disjoint used and complementary unused partitions, exact source and energy balances, and unused source mass -mass(V0). Exactly four LARGE are inserted and two returned, so G(V0)+2=G(W), U(V0)+2=U(W)+length(Rsmall), mass(V0)=v-e+L-D and H(V0)+3^abs(f(zpen))+3^abs(f(z))=H(W)+3^P+3^M+3^L+3^D. The unused SMALL set is remainingSmall(W) disjoint-union set(Rsmall). Strict J descent follows from G regardless of H; H may increase. At a minimum over ALL Legal physical lists, the actual a therefore cannot be unused."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-reused-odd-half-parent-exchange"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/OddHalfParentExchange.actualSource_used_oddHalf_parent_exchange_full"),
                H("Reuse a in its actual old prefix slot"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Suppose A=U,[a],R and u=mass(U). Either the ENTIRE actual R is compatible, meaning each positive/negative pair has combined magnitudes at most C, or the following explicit test holds at every actual LARGE i in R=R0,[i],R1: its old positive arrival mass(U,[a],R0,[i]), respectively old negative departure mass(U,[a],R0), is at most C-theta. These measurements start from original zero. No supplied new word, order, arrival or endpoint is assumed.")),
                    Paragraph(Text("Replace a's old slot by n. Old legality gives M<=u<=C, so the new start u-D lies in [0,C]. The new end a0+theta is automatically legal. For compatible full R, exists_order_between constructs Rstar. Under the old LARGE test, exists_order_preserving_large reorders every COMPLETE SMALL batch and keeps the literal LARGE order. Both lower sides survive the upward shift theta>0. A positive LARGE's old departure and a negative LARGE's old arrival are at most Q-1, hence their shifted sides remain in the strip since theta<Q; the other two upper sides are exactly the explicit test. This checks BOTH departure and arrival of every LARGE and every SMALL join.")),
                    Paragraph(Text("The complete T0 is reordered from a0+theta to v+delta+e, both derived legal endpoints. Append [beta,y,p,a]. The four final heights are v+Y+kappa, v+kappa, v+kappa+P and v-tau. The bound delta+kappa<B-d gives the upper gates, while v>tau and v+kappa=v-tau+e give the lower gates. The final word is V=U,[n],Rstar,T0star,[beta,y,p,a], with Rstar permuting R and T0star permuting T0. The literal old U may contain incompatible LARGE and is kept unchanged. The original first negative y remains and actual a is moved to the end exactly once.")),
                    Paragraph(Text("Relative to the ORIGINAL W, I=[n,beta,p] and Ret=[x,zpen,z],Rsmall. Thus V,Ret permutes W,I; exactly three LARGE are inserted and three returned. Ordinary Inventory gives used(V)=(used(W) minus set(Ret)) disjoint-union set(I), the complementary unused partition, full source balance, physical Nodup and all natural zero-start prefixes. The exact outputs are G(V)=G(W), U(V)=U(W)+length(Rsmall), remainingSmall(V)=remainingSmall(W) disjoint-union set(Rsmall), mass(V)=v-(P-L) and unused source mass=-(v-(P-L)). The exact energy balance is H(V)+3^r+3^abs(f(zpen))+3^abs(f(z))=H(W)+3^P+3^D+3^L. Since D,L<P<r, the inserted three powers sum to less than 3^r. Hence H(V)<H(W) and J(V)<J(W), independently of U."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-odd-half-sharp-remainder"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/OddHalfParentExchange.actualSource_oddHalf_sharp_remainder"),
                H("The child cancels the large prefix displacement"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("The exact inverse-source equations imply q=theta+kappa, so theta-q=-kappa. Eliminating the same source equations gives 8kappa=2D-5d-3delta. The inherited high-D inequality gives 8kappa>-d+delta+14>-d, while D<=3d-4 gives 8kappa<=d-8-3delta<d. Thus abs(8kappa)<d and abs(kappa)<Q, without an additional source or availability premise. Also 0<q<Q and the actual parent value remains f(a)=-M, with 0<D<M."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-child-after-parent-relocation"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/OddHalfParentExchange.actualSource_child_after_parent_relocation_full"),
                H("Move the actual child from after its parent"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Let the actual prefix be A=U,[a],T,[gamma],R, u=mass(U), and g=mass(U,[a],T), all measured from original zero. Require g+theta<=C and a0>=kappa. The first cut is automatic when kappa>=0, since the old gamma arrival is g+q<=C and theta=q-kappa. The second cut is automatic when kappa<=0. Old legality gives M<=u<=C, hence 0<=u-D<=C; also g+theta>=0. The same residual bound gives a0-kappa<B<C, so the other endpoint companions are derived.")),
                    Paragraph(Text("Order the ENTIRE T from u-D, an upward displacement theta from its old start u-M, ending at g+theta. Either whole-T compatibility or old LARGE HIGH sides at most C-theta suffices. HIGH means positive arrival or negative departure. Order the ENTIRE R from g+theta, ending at a0-kappa; both ends differ from the old R by -kappa. If kappa<0 require old HIGH sides at most C+kappa; if kappa>0 require old LOW sides at least kappa, where LOW means positive departure or negative arrival. Whole-R compatibility is an alternative. At kappa=0 retain literal old R. For every nonzero shift both sides of each LARGE are derived from old legality, monotonicity within the signed step and the tested extremal side. The same complete-SMALL-batch ordering theorem supplies every intervening batch and join.")),
                    Paragraph(Text("Set Astar=U,[n],Tstar,Rstar,[gamma]. The actual gamma is skipped at its old position and appended immediately before T0, ending at a0-kappa+q=a0+theta. Every prefix and join of Astar is legal from original zero. The physical identity (Astar,[a]) permutes (A,[n]) retains gamma exactly once, even when other physical labels have its numerical value."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-child-before-parent-relocation"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/OddHalfParentExchange.actualSource_child_before_parent_relocation_full"),
                H("Move the actual child from before its parent"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For the other ACTUAL order A=U,[gamma],T,[a],R, put g=mass(U), t0=mass(U,[gamma],T) and b=t0-M, the old arrival at a. Require b>=kappa and a0>=kappa; both follow from old legality when kappa<=0. Order the entire T from g instead of g+q, a downward displacement q. Either whole-T compatibility or old LARGE LOW sides at least q suffices. Since M<=t0<=C and 0<q<Q<M, its endpoint t0-q is automatically legal. Replacing a by fresh n reaches t0-q-D=b-kappa; the lower gate is the stated local cut and the upper gate follows from t0<=C and D,q>0.")),
                    Paragraph(Text("Order R with exactly the same sign-selected -kappa rule, and set Astar=U,Tstar,[n],Rstar,[gamma]. Its last two endpoints are a0-kappa and a0+theta, and (Astar,[a]) again permutes (A,[n]). Both constructions reorder the ENTIRE T0 from a0+theta to v+delta+e, then append [beta,y,p,a]. The four heights are v+Y+kappa, v+kappa, v+kappa+P and v-tau, with all bounds derived from the unchanged residual. Thus V=Astar,T0star,[beta,y,p,a], I=[n,beta,p], Ret=[x,zpen,z],Rsmall has the SAME original-W FullExchange: physical Inventory, all natural prefixes, a counted exactly once, G(V)=G(W), U(V)=U(W)+length(Rsmall), complementary source masses, and remainingSmall(V)=remainingSmall(W) disjoint-union set(Rsmall). Its exact energy identity is H(V)+3^r+3^abs(f(zpen))+3^abs(f(z))=H(W)+3^P+3^D+3^L. Since D,L<P<r the three inserted powers sum to less than 3^r, proving strict H and J descent."))),
                DescribeRole.Theorem),
            Paragraph(Text("For an ACTUAL adjacent pair A=U,[a,gamma],R, T is empty and its cut g+theta=u-D<=C is automatic in either sign. For A=U,[gamma,a],R, T is empty and the old-a-arrival cut remains. Under the applicable cuts, a minimum over ALL Legal physical lists forces whole R incompatible. Kappa=0 is impossible. If kappa<0 an actual LARGE in R has old HIGH side at least C+kappa+1; if kappa>0 an actual LARGE has old LOW side at most kappa-1. Old legality and abs(8kappa)<d put the indicated HIGH or LOW side at nonnegative distance strictly less than d/8 from its respective edge. For nonpositive kappa all local cuts in both adjacent orders are automatic. Positive kappa retains a0>=kappa and, for the reversed pair, the old-a-arrival cut. No assertion makes a nonadjacent actual pair adjacent.")),
            Paragraph(Text("At a genuine minimum over all Legal physical lists, once actual a occurs in A=U,[a],R, the full R must contain an incompatible positive/negative pair. There must also be an actual LARGE strictly after a whose old positive arrival, or old negative departure, is at least C-theta+1. The incompatible pair and the HIGH boundary need not share a witness. Endpoint legality alone does not imply a legal ordering of an arbitrary incompatible integer list: in C=5, Q=3, R=[+5,-5], old start 0 and raised start 1, neither first step fits, although both endpoints do. This example is generic and is not an actual dyadic minimum.")),
            Paragraph(Text("Strict placement of actual a before the separate reserve c uses an additional joint-resource deficit: A=Aminus,[c],K with f(c)=-m, compatible actual K, H0=a0+m, epsilon=H0-B>0, PosK the positive SMALL occurrences of K of value at most H0, and NegS the negative SMALL occurrences of S of magnitude at most min(mass(Aminus),H0). If their total signed resource Omega is at most epsilon-1, then a in K would force every positive K occurrence into PosK and force mass(PosK)>=epsilon+e, a contradiction. A global-minimum application of this stronger placement needs the actual joint-resource theorem giving that deficit; the two exchanges above assume neither a reserve nor a deficit resource.")),
            Paragraph(Text("The child relocation reduces the post-parent displacement from theta to -kappa, but does not derive every required cut or ordering criterion at a minimum. A nonadjacent pair may retain a bad middle interval, a positive-kappa local cut may fail, or the new narrow mixed HIGH/LOW barrier may remain. The actual joint-resource deficit needed for stronger reserve placement is still a separate mathematical dependency. The full odd-half parity branch and original-quantifier Circle C3.1 remain OPEN."))), []));
}
